import calendar
from datetime import date, timedelta

_WEEKDAYS = {
    "MO": 0,
    "TU": 1,
    "WE": 2,
    "TH": 3,
    "FR": 4,
    "SA": 5,
    "SU": 6,
}


def recur(start: str, rule: str, count: int) -> list[str]:
    start_date = date.fromisoformat(start)
    parts = rule.split(" ")
    freq = parts[0]
    k = int(parts[1])
    result: list[str] = []

    if freq == "DAILY":
        for i in range(count):
            result.append((start_date + timedelta(days=i * k)).isoformat())
        return result

    if freq == "WEEKLY":
        target_wds = sorted(_WEEKDAYS[code] for code in parts[2].split(","))
        week0_monday = start_date - timedelta(days=start_date.weekday())
        w = 0
        while len(result) < count:
            week_monday = week0_monday + timedelta(days=w * k * 7)
            for wd in target_wds:
                cand = week_monday + timedelta(days=wd)
                if cand >= start_date:
                    result.append(cand.isoformat())
                    if len(result) == count:
                        break
            w += 1
        return result

    if freq == "MONTHLY":
        base_months = start_date.year * 12 + (start_date.month - 1)
        m_idx = 0
        if len(parts) == 3:
            target_day = int(parts[2])
            while len(result) < count:
                year, month0 = divmod(base_months + m_idx * k, 12)
                month = month0 + 1
                days_in_month = calendar.monthrange(year, month)[1]
                m_idx += 1
                if target_day == -1:
                    day = days_in_month
                elif target_day <= days_in_month:
                    day = target_day
                else:
                    continue
                cand = date(year, month, day)
                if cand >= start_date:
                    result.append(cand.isoformat())
        else:
            nth = int(parts[2])
            target_wd = _WEEKDAYS[parts[3]]
            while len(result) < count:
                year, month0 = divmod(base_months + m_idx * k, 12)
                month = month0 + 1
                first_wd, days_in_month = calendar.monthrange(year, month)
                m_idx += 1
                if nth == -1:
                    last_wd = (first_wd + days_in_month - 1) % 7
                    day = days_in_month - (last_wd - target_wd) % 7
                else:
                    first_occ = 1 + (target_wd - first_wd) % 7
                    day = first_occ + (nth - 1) * 7
                    if day > days_in_month:
                        continue
                cand = date(year, month, day)
                if cand >= start_date:
                    result.append(cand.isoformat())
        return result

    if freq == "YEARLY":
        month_str, day_str = parts[2].split("-")
        month = int(month_str)
        day = int(day_str)
        y_idx = 0
        while len(result) < count:
            year = start_date.year + y_idx * k
            y_idx += 1
            try:
                cand = date(year, month, day)
            except ValueError:
                continue
            if cand >= start_date:
                result.append(cand.isoformat())
        return result

    raise ValueError(f"Unsupported rule: {rule}")
